// bar grow: scaleX a partir da esquerda + count-up no mesmo t
const bar = el, num = a, v = 72, max = 100;
tl.fromTo(bar, { scaleX: 0, transformOrigin: "0% 50%" }, { scaleX: v / max, duration: 0.8, ease: "power3.out" }, t);
const c = { v: 0 };
tl.fromTo(c, { v: 0 }, { v, duration: 0.8, ease: "power3.out", onUpdate: () => (num.textContent = Math.round(c.v)) }, t);

// count-up: font-variant-numeric: tabular-nums para não tremer a largura
const num = el, n = { v: 0 };
tl.fromTo(n, { v: 0 }, { v: 1000, duration: 1.0, ease: "power2.out", onUpdate: () => (num.textContent = Math.round(n.v).toLocaleString("pt-BR")) }, t);

// a = <path> da área (fill com degradê); acompanha a linha do line-chart-draw
tl.fromTo(a, { clipPath: "inset(0% 100% 0% 0%)" }, { clipPath: "inset(0% 0% 0% 0%)", duration: 1.2, ease: "none" }, t);
tl.fromTo(a, { opacity: 0 }, { opacity: 0.35, duration: 0.6, ease: "power2.out" }, t + 0.2);

// items = linhas no mesmo ponto (y = rank x rowH), cada uma com .bar dentro; states = valores normalizados por instante
const rowH = 140, states = [[0.9, 0.7, 0.5, 0.3], [0.8, 0.95, 0.6, 0.35], [0.75, 0.9, 1.0, 0.4]];
const rank = (vals) => vals.map((v) => vals.filter((w) => w > v).length);
states.forEach((vals, k) => {
  const r = rank(vals), at = t + k * 1.0;
  items.forEach((row, i) => {
    const bar = row.querySelector(".bar");
    if (k === 0) { // fromTo: linhas já no lugar desde o início, barras crescem
      tl.fromTo(row, { y: r[i] * rowH }, { y: r[i] * rowH, duration: 0.4, ease: "none" }, at);
      tl.fromTo(bar, { scaleX: 0, transformOrigin: "0% 50%" }, { scaleX: vals[i], duration: 0.4, ease: "power3.out" }, at);
    } else { tl.to(bar, { scaleX: vals[i], duration: 0.6, ease: "power1.inOut" }, at - 0.6); tl.to(row, { y: r[i] * rowH, duration: 0.5, ease: "power2.inOut" }, at - 0.5); }
  });
});

// el = imagem 'depois' por cima, a = alça da divisória
const after = el, handle = a, W = 1080;
tl.fromTo(after, { clipPath: "inset(0% 0% 0% 100%)" }, { clipPath: "inset(0% 0% 0% 20%)", duration: 0.9, ease: "power2.inOut" }, t);
tl.fromTo(handle, { x: W }, { x: W * 0.2, duration: 0.9, ease: "power2.inOut" }, t);
tl.to(after, { clipPath: "inset(0% 0% 0% 50%)", duration: 0.6, ease: "power2.inOut" }, t + 1.0);
tl.to(handle, { x: W * 0.5, duration: 0.6, ease: "power2.inOut" }, t + 1.0);

// items = [eixoX, eixoY]; .gridline e .tick no scene
const [xAxis, yAxis] = items, grid = scene.querySelectorAll(".gridline"), ticks = scene.querySelectorAll(".tick");
tl.fromTo(xAxis, { scaleX: 0, transformOrigin: "0% 50%" }, { scaleX: 1, duration: 0.5, ease: "power3.inOut" }, t);
tl.fromTo(yAxis, { scaleY: 0, transformOrigin: "50% 100%" }, { scaleY: 1, duration: 0.5, ease: "power3.inOut" }, t);
tl.fromTo(grid, { scaleX: 0, opacity: 0, transformOrigin: "0% 50%" }, { scaleX: 1, opacity: 0.25, duration: 0.4, ease: "power2.out", stagger: 0.05 }, t + 0.3);
tl.fromTo(ticks, { opacity: 0, y: 8 }, { opacity: 1, y: 0, duration: 0.25, ease: "power2.out", stagger: 0.03 }, t + 0.4);

// el = linha vertical, a = marcador, b = etiqueta; pts em px do polyline já desenhado
const pts = [[0, 600], [180, 520], [360, 560], [540, 380], [720, 300], [900, 180]], vals = [12, 18, 15, 29, 36, 48];
const vline = el, dot = a, label = b, p = { u: 0 };
tl.fromTo(p, { u: 0 }, { u: 1, duration: 2.0, ease: "power1.inOut", onUpdate: () => {
  const f = p.u * (pts.length - 1), i = Math.min(Math.floor(f), pts.length - 2), k = f - i;
  const x = pts[i][0] + (pts[i + 1][0] - pts[i][0]) * k, y = pts[i][1] + (pts[i + 1][1] - pts[i][1]) * k;
  vline.style.transform = "translateX(" + x + "px)"; dot.style.transform = "translate(" + x + "px, " + y + "px)";
  label.textContent = Math.round(vals[i] + (vals[i + 1] - vals[i]) * k) + "%";
} }, t);

// a = barra esquerda, b = barra direita, nascem do eixo central
const left = a, right = b, vA = 0.62, vB = 0.38;
tl.fromTo(left, { scaleX: 0, transformOrigin: "100% 50%" }, { scaleX: vA, duration: 0.8, ease: "power3.out" }, t);
tl.fromTo(right, { scaleX: 0, transformOrigin: "0% 50%" }, { scaleX: vB, duration: 0.8, ease: "power3.out" }, t);
tl.fromTo(left, { filter: "drop-shadow(0 0 0px rgba(208,89,44,0))" }, { filter: "drop-shadow(0 0 30px rgba(208,89,44,0.8))", duration: 0.3, ease: "power2.out" }, t + 0.8);

// items = outros pontos, el = ponto herói, a = etiqueta, b = linha guia (DrawSVGPlugin)
const others = items, hero = el, callout = a, leader = b;
tl.fromTo(others, { opacity: 1 }, { opacity: 0.25, duration: 0.35, ease: "power2.out" }, t);
tl.fromTo(hero, { scale: 1 }, { scale: 1.6, duration: 0.4, ease: "back.out(2)", transformOrigin: "50% 50%" }, t);
tl.fromTo(leader, { drawSVG: "0%" }, { drawSVG: "100%", duration: 0.3, ease: "power2.out" }, t + 0.25);
tl.fromTo(callout, { opacity: 0, y: 20 }, { opacity: 1, y: 0, duration: 0.3, ease: "power3.out" }, t + 0.45);

// DrawSVGPlugin: items = <circle> por fatia (mesmo r, stroke grosso, rotação -90°)
const vals = [45, 30, 25], total = 1.0; let acc = 0;
items.forEach((s, i) => {
  const from = acc, to = acc + vals[i]; acc = to;
  tl.fromTo(s, { drawSVG: from + "% " + from + "%" }, { drawSVG: from + "% " + to + "%", duration: total * vals[i] / 100, ease: "none" }, t + total * from / 100);
});

// el = ponteiro (origem na base), a = arco <path> semicircular (DrawSVGPlugin)
const needle = el, arc = a, pct = 0.78;
tl.fromTo(needle, { rotation: -90, transformOrigin: "50% 90%" }, { rotation: -90 + 180 * pct, duration: 1.1, ease: "elastic.out(1, 0.6)" }, t);
tl.fromTo(arc, { drawSVG: "0%" }, { drawSVG: pct * 100 + "%", duration: 0.9, ease: "power3.out" }, t);

// items = células (mesma cor no CSS); opacidade final = intensidade do dado
const data = [0.1, 0.3, 0.8, 0.5, 0.2, 0.9, 1.0, 0.6, 0.4, 0.7, 0.3, 0.1], cols = 4;
items.forEach((c, i) => tl.fromTo(c, { opacity: 0 }, { opacity: 0.08 + data[i % data.length] * 0.92, duration: 0.5, ease: "power2.out" }, t + ((i % cols) + Math.floor(i / cols)) * 0.06));

// el = <path> da linha; items = bolinhas dos pontos na ordem do eixo x
const L = el.getTotalLength(), dur = 1.2;
tl.fromTo(el, { strokeDasharray: L, strokeDashoffset: L }, { strokeDashoffset: 0, duration: dur, ease: "none" }, t);
tl.fromTo(items, { scale: 0 }, { scale: 1, duration: 0.2, ease: "back.out(2)", stagger: dur / (items.length - 1) }, t);

// el = pino, a = sombra elíptica, b = anel de impacto
const pin = el, shadow = a, ring = b;
tl.fromTo(pin, { y: -300, opacity: 0 }, { y: 0, opacity: 1, duration: 0.45, ease: "power3.in" }, t);
tl.fromTo(pin, { scaleX: 1, scaleY: 1 }, { keyframes: { scaleY: [1, 0.75, 1.08, 1], scaleX: [1, 1.2, 0.95, 1] }, duration: 0.35, ease: "none", transformOrigin: "50% 100%", immediateRender: false }, t + 0.45);
tl.fromTo(shadow, { scale: 0.3, opacity: 0 }, { scale: 1, opacity: 0.35, duration: 0.45, ease: "power3.in" }, t);
tl.fromTo(ring, { scale: 0.2, opacity: 0.8 }, { scale: 2.5, opacity: 0, duration: 0.6, ease: "power2.out" }, t + 0.45);

// DrawSVGPlugin + MotionPathPlugin: rota desenha e o marcador acompanha a ponta
const route = el, marker = a, dest = b, dur = 2.0;
tl.fromTo(route, { drawSVG: "0%" }, { drawSVG: "100%", duration: dur, ease: "power1.inOut" }, t);
tl.set(marker, { x: 0, y: 0 }, t);
tl.to(marker, { motionPath: { path: route, align: route, alignOrigin: [0.5, 0.5] }, duration: dur, ease: "power1.inOut" }, t);
tl.fromTo(dest, { scale: 0, transformOrigin: "50% 100%" }, { scale: 1, duration: 0.35, ease: "back.out(2)" }, t + dur - 0.1);

// items = colunas de dígito (tira 0-9 repetida, dentro de máscara), da esquerda para a direita
const target = "4827", H = 160, cols = items.length;
items.forEach((col, i) => {
  const d = Number(target[i]), turns = cols - 1 - i; // casas da direita giram mais
  tl.fromTo(col, { y: 0 }, { y: -(turns * 10 + d) * H, duration: 1.4 + i * 0.1, ease: "power3.out" }, t);
});

// DrawSVGPlugin: el = <circle> do anel, a = número central
const ring = el, num = a, pct = 87, c = { v: 0 };
tl.fromTo(ring, { drawSVG: "0%", rotation: -90, transformOrigin: "50% 50%" }, { drawSVG: pct + "%", duration: 1.2, ease: "power3.out" }, t);
tl.fromTo(c, { v: 0 }, { v: pct, duration: 1.2, ease: "power3.out", onUpdate: () => (num.textContent = Math.round(c.v) + "%") }, t);

// items = 100 ícones coloridos sobre 100 cinzas (grade 10x10); acende os N primeiros
const N = 27, lit = items.slice(0, N);
tl.fromTo(lit, { opacity: 0, scale: 0.6 }, { opacity: 1, scale: 1, duration: 0.2, ease: "back.out(2)", stagger: 0.8 / N }, t);

// el = preenchimento, a = etiqueta na ponta, b = número dentro da etiqueta
const fill = el, tag = a, num = b, W = 800, pct = 0.64, c = { v: 0 };
tl.fromTo(fill, { scaleX: 0, transformOrigin: "0% 50%" }, { scaleX: pct, duration: 1.0, ease: "power2.inOut" }, t);
tl.fromTo(tag, { x: 0 }, { x: W * pct, duration: 1.0, ease: "power2.inOut" }, t);
tl.fromTo(c, { v: 0 }, { v: pct * 100, duration: 1.0, ease: "power2.inOut", onUpdate: () => (num.textContent = Math.round(c.v) + "%") }, t);

// items = pontos posicionados; el = linha de tendência (DrawSVGPlugin)
const order = [3, 7, 0, 9, 5, 1, 8, 2, 6, 4];
order.forEach((idx, k) => {
  const d = items[idx];
  if (d) tl.fromTo(d, { scale: 0, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.3, ease: "back.out(2.2)" }, t + k * 0.05);
});
tl.fromTo(el, { drawSVG: "0%" }, { drawSVG: "100%", duration: 0.6, ease: "power2.inOut" }, t + order.length * 0.05 + 0.1);

// items = segmentos posicionados (left = soma dos anteriores); rótulos em .seg-label
tl.fromTo(items, { scaleX: 0, transformOrigin: "0% 50%" }, { scaleX: 1, duration: 0.4, ease: "power2.out", stagger: 0.3 }, t);
tl.fromTo(scene.querySelectorAll(".seg-label"), { opacity: 0, y: 10 }, { opacity: 1, y: 0, duration: 0.25, ease: "power2.out", stagger: 0.3 }, t + 0.25);

// el = linha de progresso, a = cabeça; items = marcos com data-at (0 a 1)
const W = 900, dur = 2.4;
tl.fromTo(el, { scaleX: 0, transformOrigin: "0% 50%" }, { scaleX: 1, duration: dur, ease: "none" }, t);
tl.fromTo(a, { x: 0 }, { x: W, duration: dur, ease: "none" }, t);
items.forEach((m) => {
  const at = t + Number(m.dataset.at) * dur;
  tl.fromTo(m, { scale: 0.6, opacity: 0.3 }, { scale: 1, opacity: 1, duration: 0.25, ease: "back.out(2)" }, at);
});
